{"op":"define","frontend":"flow","syntaxVersion":2,"source":"record InvoicePair {
    field first: Invoice;
    field second: Invoice;
}

record ReminderPairResult {
    field first: String;
    field second: String;
}

fn invoice.queue-reminders-for-pair(pair: InvoicePair) -> ReminderPairResult {
    effects fs.read, fs.write
    doc "Queue open invoice reminders in pair order and return their exact markers."

    if InvoiceStatus::value(pair.first.status) == "open" {
        let first-path = invoice::reminder-path(pair.first.id);
        let first-result =
            if file::exists?(first-path) {
                file::read(first-path)
            } else {
                file::write(first-path, "queued");
                "queued"
            };
        if InvoiceStatus::value(pair.second.status) == "open" {
            let second-path = invoice::reminder-path(pair.second.id);
            let second-result =
                if file::exists?(second-path) {
                    file::read(second-path)
                } else {
                    file::write(second-path, "queued");
                    "queued"
                };
            reminderPairResult::new(first = first-result, second = second-result)
        } else {
            reminderPairResult::new(first = first-result, second = "not-open")
        }
    } else {
        reminderPairResult::new(first = "not-open", second = "not-open")
    }
}

test invoice.queue-reminders-for-pair/two-open-missing {
    invoice::queue-reminders-for-pair(
        invoicePair::new(
            first = invoice::new(
                id = InvoiceId::new("pair-flow-missing-first"),
                status = InvoiceStatus::new("open")),
            second = invoice::new(
                id = InvoiceId::new("pair-flow-missing-second"),
                status = InvoiceStatus::new("open"))))
    => value reminderPairResult::new(first = "queued", second = "queued")
}

test invoice.queue-reminders-for-pair/exact-existing-markers {
    file::write("outbox/invoice-reminders/pair-flow-existing-first", "custom marker");
    file::write("outbox/invoice-reminders/pair-flow-empty-second", "");
    invoice::queue-reminders-for-pair(
        invoicePair::new(
            first = invoice::new(
                id = InvoiceId::new("pair-flow-existing-first"),
                status = InvoiceStatus::new("open")),
            second = invoice::new(
                id = InvoiceId::new("pair-flow-empty-second"),
                status = InvoiceStatus::new("open"))))
    => value reminderPairResult::new(first = "custom marker", second = "")
}

test invoice.queue-reminders-for-pair/second-not-open-after-first-queues {
    invoice::queue-reminders-for-pair(
        invoicePair::new(
            first = invoice::new(
                id = InvoiceId::new("pair-flow-open-first"),
                status = InvoiceStatus::new("open")),
            second = invoice::new(
                id = InvoiceId::new("pair-flow-closed-second"),
                status = InvoiceStatus::new("Open"))))
    => value reminderPairResult::new(first = "queued", second = "not-open")
}

test invoice.queue-reminders-for-pair/first-not-open-skips-open-second {
    invoice::queue-reminders-for-pair(
        invoicePair::new(
            first = invoice::new(
                id = InvoiceId::new("pair-flow-closed-first"),
                status = InvoiceStatus::new("Open")),
            second = invoice::new(
                id = InvoiceId::new("pair-flow-open-second"),
                status = InvoiceStatus::new("open"))))
    => value reminderPairResult::new(first = "not-open", second = "not-open")
}

example invoice.queue-reminders-for-pair/queues-second-in-order {
    invoice::queue-reminders-for-pair(
        invoicePair::new(
            first = invoice::new(
                id = InvoiceId::new("pair-flow-example-first"),
                status = InvoiceStatus::new("open")),
            second = invoice::new(
                id = InvoiceId::new("pair-flow-example-second"),
                status = InvoiceStatus::new("open")))).second
    => "queued"
}"}

